(function(){
'use strict';
const esc112=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const isAdmin112=()=>String(window.state?.profile?.rol||'').toUpperCase()==='ADMIN_TOTAL';
async function edge112(path,body){const r=await req(path,{method:'POST',body:JSON.stringify(body||{})});if(!r?.data?.ok)throw Object.assign(new Error(r?.data?.error||'No se pudo completar la operación'),{data:r?.data});return r.data}
function niceErr112(e){const x=String(e?.message||e);return ({panapass_asignado_a_otra_unidad:'Ese Panapass ya está asignado a otra unidad.',pin_asignado_a_otra_unidad:'Ese PIN ya está asignado a otra unidad.',unidad_cerrada_no_puede_tener_cupo:'Una unidad cerrada o canibalizada no puede tener cupo asignado.'}[x]||x)}
function addMasterEditor112(r){if(!isAdmin112())return;const m=document.querySelector('#ca6UnitModal');if(!m||m.querySelector('.v112-master-edit'))return;const anchor=m.querySelector('.v74-control-edit')||m.querySelector('.ca6-ena-card');const box=document.createElement('section');box.className='v112-master-edit';box.innerHTML=`<h3>Datos maestros de la unidad</h3><div class="muted">Panapass y PIN se administran desde Control de Auto. Chasis, motor y año se contrastan contra eCarCheck.</div><div class="v112-master-grid"><div class="field"><label>Panapass</label><input id="v112Pan" value="${esc112(r.panapass_numero||'')}" placeholder="Número Panapass"></div><div class="field"><label>PIN</label><input id="v112Pin" value="${esc112(r.pin||'')}" placeholder="PIN"></div></div><div class="v112-master-actions"><button id="v112SavePan">Validar y guardar Panapass</button><button id="v112SavePin">Guardar PIN</button></div><div class="v112-master-msg" id="v112MasterMsg"></div>`;(anchor?.parentNode||m.querySelector('.user-modal-card')||m).insertBefore(box,anchor||null);const msg=box.querySelector('#v112MasterMsg');
 const save=async(action,val,btn)=>{btn.disabled=true;const old=btn.textContent;btn.textContent='Guardando...';try{if(action==='PANAPASS'){const n=Number(String(val).replace(/\D/g,''));if(!n)throw Error('Número Panapass inválido.');try{const x=await req('/functions/v1/ena-consulta-saldo',{method:'POST',body:JSON.stringify({panapass:n})});const rr=x?.data?.results?.[0];if(rr&&rr.result==='OK')msg.innerHTML='<div class="success">Panapass confirmado en ENA. Guardando asignación...</div>';else msg.innerHTML='<div class="v112-special">ENA no confirmó saldo en este momento. Se validará duplicidad interna antes de guardar.</div>'}catch(_){msg.innerHTML='<div class="v112-special">No fue posible confirmar ENA ahora. Se validará duplicidad interna antes de guardar.</div>'}}
 const d=await edge112('/functions/v1/control-auto-editar',{action,unidad:r.unidad,valor:val});msg.innerHTML=`<div class="success">${action==='PIN'?'PIN':'Panapass'} actualizado y auditado.</div>`;if(action==='PANAPASS')r.panapass_numero=d.nuevo||val;else r.pin=d.nuevo||val;setTimeout(()=>document.querySelector('#ca6Go')?.click(),500)}catch(e){msg.innerHTML=`<div class="alert">${esc112(niceErr112(e))}</div>`}finally{btn.disabled=false;btn.textContent=old}};
 box.querySelector('#v112SavePan').onclick=()=>save('PANAPASS',box.querySelector('#v112Pan').value.trim(),box.querySelector('#v112SavePan'));box.querySelector('#v112SavePin').onclick=()=>save('PIN',box.querySelector('#v112Pin').value.trim(),box.querySelector('#v112SavePin'));
}
const oldOpen112=window.phase6OpenUnit||globalThis.phase6OpenUnit;if(typeof oldOpen112==='function'){const wrapped=function(r){oldOpen112(r);setTimeout(()=>addMasterEditor112(r),60)};window.phase6OpenUnit=wrapped;try{phase6OpenUnit=wrapped}catch(_){}}
async function addAuditMaster112(){if(!isAdmin112())return;const out=document.querySelector('#ca6Out');if(!out||out.querySelector('#v112AuditMaster'))return;try{const d=await edge112('/functions/v1/control-auto-auditoria-v112',{}),k=d.kpis||{};const sec=document.createElement('section');sec.id='v112AuditMaster';sec.className='v112-audit-master';const bajas=(d.bajas_ecarcheck||[]);sec.innerHTML=`<div class="ca-audit-section"><h3>Integridad maestra Control de Auto vs eCarCheck</h3><div class="ca-audit-note">Regla V112: cuando la ficha eCarCheck es válida, eCarCheck manda para chasis, motor, año, color y cupo.</div><div class="v112-audit-kpis"><div class="v112-audit-kpi"><span>Sin Panapass</span><strong>${Number(k.sin_panapass||0)}</strong></div><div class="v112-audit-kpi"><span>Sin PIN</span><strong>${Number(k.sin_pin||0)}</strong></div><div class="v112-audit-kpi"><span>Diferencias maestras</span><strong>${Number(k.diferencias_maestras||0)}</strong></div><div class="v112-audit-kpi"><span>Cupo en cerradas</span><strong>${Number(k.cupos_en_cerradas||0)}</strong></div><div class="v112-audit-kpi"><span>Control con cupo / eCarCheck sin</span><strong>${Number(k.control_cupo_sin_ecarcheck||0)}</strong></div><div class="v112-audit-kpi"><span>Activas BAJA eCarCheck</span><strong>${Number(k.activas_baja_ecarcheck||0)}</strong></div></div>${bajas.map(x=>`<div class="v112-special"><b>${esc112(x.unidad)} · ${esc112(x.placa)}</b> — ${esc112(x.clasificacion)}<br>${esc112(x.propietario||'')} · eCarCheck: ${esc112(x.estado_ecarcheck||'')} · Cupo eCarCheck: ${esc112(x.cupo_ecarcheck||'Sin cupo')}</div>`).join('')}</div>`;out.prepend(sec)}catch(e){console.warn('V112 audit master',e)}}
const mo=new MutationObserver(()=>{if(document.body.classList.contains('v70-control')){document.body.dataset.v112control='1';if(document.querySelector('#ca6Audit')?.classList.contains('active'))setTimeout(addAuditMaster112,80)}});mo.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
document.addEventListener('click',e=>{if(e.target?.closest?.('#ca6Audit,[data-v75-control="auditoria"]'))setTimeout(addAuditMaster112,450)},true);
})();
